import type { PlayerBottomBarKind } from "@/types/core/view";
import type { MpvChapter, MpvTrack } from "@/types/player/videoPlayer";
import type { PlayerStream } from "@/types/player/playerStream";

export interface PlayerBottomBarProps {
  variant: PlayerBottomBarKind;
  playerType: "default" | "modern";
  hasFile: boolean;
  paused: boolean;
  duration: number;
  chapters: MpvChapter[];
  tracks: MpvTrack[];
  hasPrev: boolean;
  hasNext: boolean;
  immersive: boolean;
  autoHide: boolean;
  speed: number;
  volume: number;
  muted: boolean;
  playlistOpen: boolean;
  seekTarget: number | null;
  onPlay: () => void;
  onPause: () => void;
  onPlayPause: () => void;
  onSeekTo: (seconds: number) => void;
  onScrub: (time: number) => void;
  onCommitSeek: (time: number) => void;
  onFilePrev: () => void;
  onFileNext: () => void;
  onFrameStep: (forward: boolean) => void;
  onCycleSub: () => void;
  onSpeed: (speed: number) => void;
  onVolume: (volume: number) => void;
  onMute: () => void;
  onToggleAutoHide: () => void;
  onTogglePlaylist: () => void;
  onSelectAudio: (id: number | "no") => void;
  onSelectSub: (id: number | "no") => void;
  onAddAudio: () => void;
  onAddSubtitle: () => void;
  hideTracks: boolean;
  stream: PlayerStream;
}
